static TEE_Result copy_in_attrs(struct user_ta_ctx *utc, /* <=== copy_in_attrs */ 
			const struct utee_attribute *usr_attrs,
			uint32_t attr_count, TEE_Attribute *attrs)
{
	TEE_Result res;
	uint32_t n;

	res = tee_mmu_check_access_rights(utc,
			TEE_MEMORY_ACCESS_READ | TEE_MEMORY_ACCESS_ANY_OWNER,
			(uaddr_t)usr_attrs,
			attr_count * sizeof(struct utee_attribute));
	if (res != TEE_SUCCESS)
		return res;

	for (n = 0; n < attr_count; n++) {
		attrs[n].attributeID = usr_attrs[n].attribute_id;
		if (attrs[n].attributeID & TEE_ATTR_BIT_VALUE) {
			attrs[n].content.value.a = usr_attrs[n].a;
			attrs[n].content.value.b = usr_attrs[n].b;
		} else {
			uintptr_t buf = usr_attrs[n].a;
			size_t len = usr_attrs[n].b;

			res = tee_mmu_check_access_rights(utc,
				TEE_MEMORY_ACCESS_READ |
				TEE_MEMORY_ACCESS_ANY_OWNER, buf, len);
			if (res != TEE_SUCCESS)
				return res;
			attrs[n].content.ref.buffer = (void *)buf;
			attrs[n].content.ref.length = len;
		}
	}

	return TEE_SUCCESS;
}

TEE_Result tee_obj_get(struct user_ta_ctx *utc, uint32_t obj_id, /* <=== tee_obj_get */ 
		       struct tee_obj **obj)
{
	struct tee_obj *o;

	TAILQ_FOREACH(o, &utc->objects, link) {
		if (obj_id == (vaddr_t)o) {
			*obj = o;
			return TEE_SUCCESS;
		}
	}
	return TEE_ERROR_BAD_PARAMETERS;
}

TEE_Result crypto_acipher_rsanopad_decrypt(struct rsa_keypair *key, /* <=== crypto_acipher_rsanopad_decrypt */ 
					   const uint8_t *src, size_t src_len,
					   uint8_t *dst, size_t *dst_len);

bool tee_mmu_is_vbuf_inside_ta_private(const struct user_ta_ctx *utc, /* <=== tee_mmu_is_vbuf_inside_ta_private */ 
				  const void *va, size_t size)
{
	struct vm_region *r;

	TAILQ_FOREACH(r, &utc->vm_info->regions, link) {
		if (r->attr & (TEE_MATTR_EPHEMERAL | TEE_MATTR_PERMANENT))
			continue;
		if (core_is_buffer_inside(va, size, r->va, r->size))
			return true;
	}

	return false;
}

TEE_Result crypto_acipher_ecc_sign(uint32_t algo, struct ecc_keypair *key, /* <=== crypto_acipher_ecc_sign */ 
				   const uint8_t *msg, size_t msg_len,
				   uint8_t *sig, size_t *sig_len);

static void *raw_malloc(size_t hdr_size, size_t ftr_size, size_t pl_size, /* <=== raw_malloc */ 
			struct bpoolset *poolset)
{
	void *ptr = NULL;
	bufsize s;

	/*
	 * Make sure that malloc has correct alignment of returned buffers.
	 * The assumption is that uintptr_t will be as wide as the largest
	 * required alignment of any type.
	 */
	COMPILE_TIME_ASSERT(SizeQuant >= sizeof(uintptr_t));

	raw_malloc_validate_pools();

	/* Compute total size */
	if (ADD_OVERFLOW(pl_size, hdr_size, &s))
		goto out;
	if (ADD_OVERFLOW(s, ftr_size, &s))
		goto out;

	/* BGET doesn't like 0 sized allocations */
	if (!s)
		s++;

	ptr = bget(s,  poolset);
out:
	raw_malloc_return_hook(ptr, pl_size, poolset);

	return ptr;
}

